/*
 * t_cover.c -- decoder-completeness test for package V20.
 *
 * space_v20.h is generated by gen_space.py from llvm-mc's disassembler over the three encoding spaces:
 * every word llvm decodes to a mnemonic V20 implements must execute (N2A32_OK), and the two half-precision
 * conversions V20 deliberately leaves out must return N2A32_UNDEF.  Words llvm rejects are not listed; the
 * random sweep (t_sweep) covers them for "never crash, never anything but OK/UNDEF".
 */
#include "n2a32.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "space_v20.h"

#define MEMSZ (16u << 20)
#define BASE  0x8000u

/* the MMIO hooks live in the core (V02); no test marks a megabyte as MMIO */
uint32_t n2a32_mmio_load(struct n2a32_mem *m, uint32_t a, unsigned bytes)
{
	(void)m; (void)a; (void)bytes;
	return 0;
}

void n2a32_mmio_store(struct n2a32_mem *m, uint32_t a, unsigned bytes, uint32_t v)
{
	(void)m; (void)a; (void)bytes; (void)v;
}

static struct n2a32_cpu cpu;
static struct n2a32_mem m;
static uint8_t *mem;
static int checks, fails;

/* run one word through both class functions; ldst words (top nibble 0xF4) go to n2a32_neon_ldst */
static int run_word(uint32_t w)
{
	memset(&cpu, 0, sizeof cpu);
	m.base = mem;
	cpu.mem = &m;
	cpu.r[0] = BASE;
	cpu.r[1] = BASE;
	cpu.r[2] = BASE + 4;
	if ((w & 0xFF000000u) == 0xF4000000u) {
		int r = n2a32_neon_ldst(&cpu, w);

		/* VLDn to all lanes with a store encoding is architecturally UNDEFINED; gen_space only lists
		 * words llvm decodes, and llvm does not decode those, so an UNDEF here is acceptable only for
		 * the documented list. */
		return r;
	}
	return n2a32_neon_misc(&cpu, w);
}

int main(void)
{
	unsigned i;

	mem = calloc(1, MEMSZ);
	if (!mem) {
		printf("FAIL calloc\n");
		return 1;
	}
	for (i = 0; i < SPACE_OK_COUNT; i++) {
		int r = run_word(space_ok[i]);

		checks++;
		if (r != N2A32_OK) {
			fails++;
			printf("FAIL %08x should execute, got %d\n", space_ok[i], r);
			if (fails > 20)
				break;
		}
	}
	for (i = 0; i < SPACE_UNDEF_COUNT; i++) {
		int r = run_word(space_undef[i]);

		checks++;
		if (r != N2A32_UNDEF) {
			fails++;
			printf("FAIL %08x should be UNDEF, got %d\n", space_undef[i], r);
		}
	}
	/* The other direction: every word of the spaces that llvm-mc's disassembler rejects (with
	 * registers that cannot wrap) is an unallocated encoding and must be UNDEF too, not executed
	 * as some instruction. */
	for (i = 0; i < SPACE_BAD_COUNT; i++) {
		int r = run_word(space_bad[i]);

		checks++;
		if (r != N2A32_UNDEF) {
			fails++;
			printf("FAIL %08x unallocated but got %d\n", space_bad[i], r);
			if (fails > 20)
				break;
		}
	}
	free(mem);
	printf("t_cover: %d checks, %d failures\n", checks, fails);
	return fails == 0 ? 0 : 1;
}
